import attr

from taf.ul.ue.sim.env_setup.devices.bts import BTS


@attr.s(cmp=False, hash=True)
class GNB(BTS):
    def _get_vlan_id(self):
        try:
            return self.configuration.cu.s1u.vlan_id
        except Exception:
            return None

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.dus[0].airscale.common_units[0].lmp_connection.addr

    def _get_taf_pdu_config(self):
        return self.configuration.dus[0].airscale.common_units[0].pdu_port

    def _get_lmp_password(self) -> str:
        return self.configuration.dus[0].airscale.common_units[0].lmp_connection.password
